 "content": "def transform(grid):
    n = len(grid)
    transposed = [list(row) for row in zip(*grid)]

    def index(i):
        tile, offset = divmod(i, n)
        return offset if tile % 2 == 0 else n - 1 - offset

    return [
        [transposed[index(r)][index(c)] for c in range(3 * n)]
        for r in range(3 * n)
    ]
